<?php
namespace App\Controllers\Api;
class BootstrapController extends BaseApiController
{
 public function index(){ $u=$this->currentUser();$role=$u['peran'];$db=db_connect();$calendar=\App\Libraries\SchoolCalendar::info(new \DateTimeImmutable('now'));$missingStatus=$calendar['status']??'Menunggu keterangan';$semester=$this->request->getGet('semester')?:'Ganjil';if(!in_array($semester,['Ganjil','Genap'],true))$semester='Ganjil';$active=$db->table('tahun_ajaran')->where('aktif',1)->get()->getRowArray();$classes=$db->table('kelas')->select('kelas.id,kelas.nama_kelas,kelas.tingkat,kelas.jurusan,tahun_ajaran.nama_tahun_ajaran,tahun_ajaran.semester')->join('tahun_ajaran','tahun_ajaran.id=kelas.tahun_ajaran_id')->where('tahun_ajaran.aktif',1)->get()->getResultArray();if($role==='guru'){$assigned=\App\Libraries\TeacherAssignments::rows(null,(int)($u['guru_id']??0));$classIds=array_column($assigned,'kelas_id');$classes=array_values(array_filter($classes,static fn($c)=>in_array($c['id'],$classIds)));}$requested=(int)$this->request->getGet('kelas_id');$allowed=array_map('intval',array_column($classes,'id'));$selected=in_array($requested,$allowed,true)?$requested:(int)($classes[0]['id']??0);if(in_array($role,['siswa','sekretaris'],true)){$own=$db->table('siswa')->select('kelas_id')->where(['nis'=>$u['nis'],'aktif'=>1])->get()->getRowArray();$selected=(int)($own['kelas_id']??0);if($role==='sekretaris')$classes=array_values(array_filter($classes,static fn($c)=>(int)$c['id']===$selected));}$result=['publicSummary'=>['namaSekolah'=>'SMK Negeri 19 Jakarta','jumlahKelas'=>count($classes),'tahunAjaran'=>$active],'classes'=>$role==='guest'?[]:$classes,'selectedClassId'=>$selected,'legacyStudents'=>[],'studentDetails'=>[],'schoolTeachers'=>[],'teacherContacts'=>[],'communications'=>[],'notifications'=>[],'dashboard'=>[],'lateCounts'=>[],'semester'=>$semester,'kalender'=>$calendar];if($role==='guru'){$map=[];foreach(\App\Libraries\TeacherAssignments::rows($selected,(int)($u['guru_id']??0)) as $a)$map[$a['mata_pelajaran_id']]=['id'=>$a['mata_pelajaran_id'],'nama_mata_pelajaran'=>$a['nama_mata_pelajaran']];$result['teacherSubjects']=array_values($map);}if($role==='guest')return $this->respond($result);$students=$db->table('siswa')->select("siswa.*,COALESCE(absensi.status,".$db->escape($missingStatus).") status_absensi")->join('absensi',"absensi.siswa_id=siswa.id AND absensi.kelas_id=siswa.kelas_id AND absensi.tanggal='".date('Y-m-d')."' AND absensi.semester='".$semester."'",'left')->where('siswa.aktif',1)->where('siswa.kelas_id',$selected);if($role==='siswa')$students->where('siswa.nis',$u['nis']);$rows=$students->orderBy('siswa.nama_lengkap')->get()->getResultArray();if(\App\Libraries\SchoolCalendar::attendanceOverride($calendar['tanggal'])!==null)foreach($rows as &$row)$row['status_absensi']=$calendar['status'];unset($row);foreach($rows as $s){$result['legacyStudents'][]=[$s['nama_lengkap'],$s['nis'],$s['status_absensi'],$this->initials($s['nama_lengkap']),$s['jenis_kelamin'],$role==='wali_kelas'?($s['nomor_hp']??''):'',$role==='wali_kelas'?($s['nomor_hp_orang_tua']??''):'',(int)$s['id']];$result['studentDetails'][$s['nis']]=$this->detail($s,$role==='wali_kelas');}$counts=[];foreach($rows as $row){$status=$row['status_absensi'];$counts[$status]=($counts[$status]??0)+1;}$lateRows=$db->table('absensi')->select('siswa_id,COUNT(*) AS jumlah')->where(['kelas_id'=>$selected,'status'=>'Terlambat'])->whereNotIn('tanggal',\App\Libraries\SchoolCalendar::attendanceOverrideDates())->groupBy('siswa_id')->get()->getResultArray();foreach($lateRows as $lateRow){$result['lateCounts'][(string)$lateRow['siswa_id']]=(int)$lateRow['jumlah'];}$result['dashboard']=['total'=>count($rows),'status'=>$counts,'tanggal'=>date('Y-m-d')];$attachmentDetails=new \App\Libraries\AttendanceAttachmentDetails($selected,array_column($rows,'id'),$calendar['tanggal'],$calendar['tanggal']);$result['dashboard']['attachment_notes']=[];foreach($rows as $row)$result['dashboard']['attachment_notes'][(string)$row['id']]=$attachmentDetails->forAttendance((int)$row['id'],$calendar['tanggal'],$row['status_absensi'])['keterangan_lampiran'];if($role==='wali_kelas'){$result['communications']=$db->table('pesan_komunikasi')->select('pesan_komunikasi.*,siswa.nama_lengkap')->join('siswa','siswa.id=pesan_komunikasi.siswa_id','left')->where('pesan_komunikasi.kelas_id',$selected)->orderBy('pesan_komunikasi.id','DESC')->limit(10)->get()->getResultArray();}[$notificationStart,$notificationEnd]=\App\Libraries\NotificationDate::range(\App\Libraries\NotificationDate::today());$result['notifications']=$db->table('notifikasi')->where('pengguna_id',$u['id'])->where('dibuat_pada >=',$notificationStart)->where('dibuat_pada <',$notificationEnd)->orderBy('dibuat_pada','DESC')->orderBy('id','DESC')->limit(10)->get()->getResultArray();if($role==='wali_kelas'){$teachers=$db->table('guru')->where('aktif',1)->orderBy('urutan','ASC')->orderBy('nama_lengkap')->get()->getResultArray();foreach($teachers as $i=>$t){$result['schoolTeachers'][]=['no'=>$i+1,'name'=>$t['nama_lengkap'],'call'=>$t['nama_panggilan'],'gender'=>$t['jenis_kelamin'],'id'=>$t['nip_nikki'],'nrk'=>$t['nrk'],'nuptk'=>$t['nuptk'],'nik'=>$t['nik'],'birth'=>$t['tempat_tanggal_lahir'],'position'=>$t['jabatan'],'subject'=>$t['mata_pelajaran'],'address'=>$t['alamat'],'phone'=>$t['nomor_hp'],'email'=>$t['email']];}$assignments=\App\Libraries\TeacherAssignments::rows($selected);foreach($assignments as $assignment){$result['teacherContacts'][$assignment['nama_mata_pelajaran']]=['name'=>$assignment['nama_guru'],'phone'=>$assignment['nomor_hp']??''];}}return $this->respond($result);}
 private function initials(string $name):string{$parts=preg_split('/\s+/',trim($name));return strtoupper(substr($parts[0]??'',0,1).substr($parts[1]??'',0,1));}
 private function detail(array $s,bool $full):array{if(!$full)return ['Nama Siswa'=>$s['nama_lengkap'],'NIS'=>$s['nis'],'Jenis Kelamin'=>$s['jenis_kelamin']];return ['Nama Siswa'=>$s['nama_lengkap'],'NIS'=>$s['nis'],'NISN'=>$s['nisn'],'Jenis Kelamin'=>$s['jenis_kelamin']==='L'?'Laki-laki':'Perempuan','Tempat Lahir'=>$s['tempat_lahir'],'Tanggal Lahir'=>$s['tanggal_lahir'],'Agama'=>$s['agama'],'Alamat Lengkap'=>$s['alamat_lengkap'],'Status tempat tinggal saat ini'=>$s['status_tempat_tinggal'],'Transportasi utama ke sekolah'=>$s['transportasi'],'Nama Ayah'=>$s['nama_ayah'],'Nama Ibu'=>$s['nama_ibu'],'Nama wali (jika tinggal bersama wali) '=>$s['nama_wali'],'Hubungan wali dengan siswa'=>$s['hubungan_wali'],'Jumlah saudara kandung'=>$s['jumlah_saudara'],'Anak ke '=>$s['anak_ke'],'Pekerjaan ayah'=>$s['pekerjaan_ayah'],'Pekerjaan ibu'=>$s['pekerjaan_ibu'],'Apakah siswa menerima bantuan pendidikan?'=>$s['menerima_bantuan']?'Ya':'Tidak','Apakah siswa mengidap penyakit/penyakit bawaan'=>$s['memiliki_penyakit']?'Ya':'Tidak','Jika jawaban YA, penyakit apa yang harus diketahui Wali Kelas'=>$s['catatan_penyakit'],'Hobi/kegiatan yang sering dilakukan'=>$s['hobi'],'Kegiatan ekskul yang diikuti'=>$s['kegiatan_ekskul']??null,'Prestasi atau kelebihan yang pernah diraih '=>$s['prestasi']];}
}